//! Shared visual recipes between the theme tokens and the components.
//!
//! shadcn expresses these as Tailwind class strings; here each one is a function
//! that applies the same styles to any GPUI element, so every component draws
//! surfaces, controls, focus, text and images the same way, and a change to a
//! recipe reaches the whole catalog. The registry lint fails components that
//! rewrite one of these by hand. Everything takes `&UiTheme` so it works in
//! `RenderOnce` and `Render` alike without re-reading the global.

use gpui_icons::{LucideIcon, lucide};
use gpui_kit::{
    AnyElement, Axis, BoxShadow, Div, FontWeight, ImageSource, Img, InteractiveElement,
    IntoElement, MouseButton, ObjectFit, ParentElement, Pixels, Rgba, SharedString,
    StatefulInteractiveElement, StyleRefinement, Styled, StyledImage as _, Window, div, img, px,
};

use super::{UiTextStyle, UiTheme};

/// Text sizes from the type scale, each with its line height and the body font.
pub mod text {
    use super::*;

    /// Applies one step of the type scale and the body font.
    pub fn style<T: Styled>(element: T, theme: &UiTheme, style: UiTextStyle) -> T {
        let style = theme.text_style(style);
        element
            .font_family(theme.fonts.body.clone())
            .text_size(style.size)
            .line_height(style.line_height)
    }
    /// Captions, key caps and timestamps.
    pub fn xs<T: Styled>(element: T, theme: &UiTheme) -> T {
        style(element, theme, theme.typography.xs)
    }
    /// Controls and body copy; the Nova default.
    pub fn sm<T: Styled>(element: T, theme: &UiTheme) -> T {
        style(element, theme, theme.typography.sm)
    }
    /// Prose and dialog titles.
    pub fn base<T: Styled>(element: T, theme: &UiTheme) -> T {
        style(element, theme, theme.typography.base)
    }
    /// Section headings.
    pub fn lg<T: Styled>(element: T, theme: &UiTheme) -> T {
        style(element, theme, theme.typography.lg)
    }
    /// Page headings.
    pub fn xl<T: Styled>(element: T, theme: &UiTheme) -> T {
        style(element, theme, theme.typography.xl)
    }
    /// A medium-weight heading in the heading font at the given step.
    pub fn heading<T: Styled>(element: T, theme: &UiTheme, size: UiTextStyle) -> T {
        style(element, theme, size)
            .font_family(theme.fonts.heading.clone())
            .font_weight(FontWeight::MEDIUM)
    }
    /// Switches to the monospace font, keeping the current size.
    pub fn mono<T: Styled>(element: T, theme: &UiTheme) -> T {
        element.font_family(theme.fonts.mono.clone())
    }
    /// Muted supporting text at the small size.
    pub fn muted<T: Styled>(element: T, theme: &UiTheme) -> T {
        sm(element, theme).text_color(theme.colors.muted_foreground)
    }
}

/// Icon sizes in spacing units, so icons scale with control density.
pub mod icon {
    use super::*;

    /// 12px: inside badges and tags.
    pub fn xs(theme: &UiTheme) -> Pixels {
        theme.space(3.)
    }
    /// 14px: inside small buttons and chips.
    pub fn sm(theme: &UiTheme) -> Pixels {
        theme.space(3.5)
    }
    /// 16px: the default inside controls and menu items.
    pub fn md(theme: &UiTheme) -> Pixels {
        theme.space(4.)
    }
    /// 20px: list leading icons.
    pub fn lg(theme: &UiTheme) -> Pixels {
        theme.space(5.)
    }
    /// 24px: empty states and headers.
    pub fn xl(theme: &UiTheme) -> Pixels {
        theme.space(6.)
    }
}

/// Keyboard focus treatment: shadcn Nova's `ring-3 ring-ring/50` outside the
/// border, with the border taking the ring color. Apply through
/// `focus_visible` so pointer presses leave it alone.
pub mod focus {
    use super::*;

    /// The ring as a box shadow, for elements that draw their own border.
    pub fn shadow(color: Rgba) -> Vec<BoxShadow> {
        vec![BoxShadow::new(px(0.), px(0.), color.into()).spread_radius(px(3.))]
    }
    /// The focus ring for an ordinary control.
    pub fn ring(style: StyleRefinement, theme: &UiTheme) -> StyleRefinement {
        let control = theme.control();
        style
            .border_color(theme.colors.ring)
            .shadow(shadow(control.ring))
    }
    /// The focus ring for an invalid control, in the destructive color.
    pub fn invalid_ring(style: StyleRefinement, theme: &UiTheme) -> StyleRefinement {
        let control = theme.control();
        style
            .border_color(theme.colors.destructive)
            .shadow(shadow(control.invalid_ring))
    }
    /// Picks the valid or invalid ring.
    pub fn ring_for(style: StyleRefinement, theme: &UiTheme, invalid: bool) -> StyleRefinement {
        if invalid {
            invalid_ring(style, theme)
        } else {
            ring(style, theme)
        }
    }
    /// Draws the ring on `element` while `focused`, for controls whose focus is
    /// tracked on a parent (a grouped checkbox or radio draws it on its box).
    pub fn shown<T: Styled>(element: T, theme: &UiTheme, focused: bool) -> T {
        shown_for(element, theme, focused, false)
    }
    /// [`shown`] with the invalid ring when `invalid`.
    pub fn shown_for<T: Styled>(element: T, theme: &UiTheme, focused: bool, invalid: bool) -> T {
        if focused {
            super::super::apply_style(
                element,
                &ring_for(StyleRefinement::default(), theme, invalid),
            )
        } else {
            element
        }
    }
}

/// Disabled and interactive cursor treatment.
pub mod disabled {
    use super::*;

    /// Nova's `disabled:opacity-50` plus the blocked cursor.
    pub fn style<T: Styled>(element: T) -> T {
        element.opacity(0.5).cursor_not_allowed()
    }
    /// A pointer cursor when enabled, the disabled treatment otherwise.
    pub fn interactive<T: Styled>(element: T, disabled: bool) -> T {
        if disabled {
            style(element)
        } else {
            element.cursor_pointer()
        }
    }
    /// Half opacity while `dimmed`, for content that is unavailable rather than
    /// a control that is disabled: uploading pictures, disabled list rows.
    pub fn dim<T: Styled>(element: T, dimmed: bool) -> T {
        if dimmed {
            element.opacity(0.5)
        } else {
            element
        }
    }
}

/// Elevated surfaces. One rule per kind, so every popover, menu, dialog, card
/// and tooltip in the catalog shares border, radius, shadow and text defaults.
pub mod surface {
    use super::*;

    fn popover_base<T: Styled>(element: T, theme: &UiTheme) -> T {
        text::sm(element, theme)
            .border_1()
            .border_color(theme.control().surface_border)
            .bg(theme.colors.popover)
            .text_color(theme.colors.popover_foreground)
    }
    /// Popovers, hover cards, select and combobox lists: `rounded-lg shadow-md`.
    pub fn popover<T: Styled>(element: T, theme: &UiTheme) -> T {
        popover_base(element, theme)
            .rounded(theme.radius.lg)
            .shadow(theme.shadows.md.to_vec())
    }
    /// Menus and context menus: a popover with Nova's 4px inset.
    pub fn menu<T: Styled>(element: T, theme: &UiTheme) -> T {
        popover(element, theme).p(theme.space(1.))
    }
    /// Dialogs and command palettes: `rounded-xl shadow-lg`.
    pub fn modal<T: Styled>(element: T, theme: &UiTheme) -> T {
        popover_base(element, theme)
            .rounded(theme.radius.xl)
            .shadow(theme.shadows.lg.to_vec())
    }
    /// A sheet or drawer panel: the modal surface without a radius, which the
    /// caller rounds on the open edge.
    pub fn sheet<T: Styled>(element: T, theme: &UiTheme) -> T {
        popover_base(element, theme).border_color(theme.colors.border)
    }
    /// Toasts: `rounded-2xl` on the popover surface with the plain border.
    pub fn toast<T: Styled>(element: T, theme: &UiTheme) -> T {
        popover_base(element, theme)
            .rounded(theme.radius.two_xl)
            .border_color(theme.colors.border)
            .shadow(theme.shadows.lg.to_vec())
    }
    /// Cards and empty states: `rounded-xl border shadow-sm` on the card color.
    pub fn card<T: Styled>(element: T, theme: &UiTheme) -> T {
        text::sm(element, theme)
            .rounded(theme.radius.xl)
            .border_1()
            .border_color(theme.colors.border)
            .bg(theme.colors.card)
            .text_color(theme.colors.card_foreground)
            .shadow(theme.shadows.sm.to_vec())
    }
    /// A floating action bar over content, as on a hovered message.
    pub fn floating<T: Styled>(element: T, theme: &UiTheme) -> T {
        element
            .rounded(theme.radius.lg)
            .border_1()
            .border_color(theme.colors.border)
            .bg(theme.colors.background)
            .shadow(theme.shadows.sm.to_vec())
    }
    /// Tooltips: inverted colors at the small radius and caption size.
    pub fn tooltip<T: Styled>(element: T, theme: &UiTheme) -> T {
        text::xs(element, theme)
            .rounded(theme.radius.sm)
            .px(theme.space(3.))
            .py(theme.space(1.5))
            .bg(theme.colors.foreground)
            .text_color(theme.colors.background)
    }
    /// A one-pixel rule in the border color, across or down.
    pub fn divider<T: Styled>(element: T, theme: &UiTheme, axis: Axis) -> T {
        let element = match axis {
            Axis::Horizontal => element.w_full().h(px(1.)),
            Axis::Vertical => element.h_full().w(px(1.)),
        };
        element.bg(theme.colors.border)
    }
}

/// Form control pieces shared by single controls and their grouped variants.
pub mod control {
    use super::*;

    /// Corner radius of a 16px check box: Nova's `rounded-[4px]` at the default radius.
    pub fn box_radius(theme: &UiTheme) -> Pixels {
        theme.radius.sm * (2. / 3.)
    }

    /// The frame every text-like control shares: inputs, textareas, selects,
    /// number and OTP cells. Large radius, input border and fill, small text.
    /// Callers set the size: `h(theme.space(8.))` and `px(theme.space(2.5))`
    /// for a single-line control.
    pub fn frame<T: Styled>(element: T, theme: &UiTheme, invalid: bool) -> T {
        let control = theme.control();
        text::sm(element, theme)
            .rounded(theme.radius.lg)
            .border_1()
            .border_color(if invalid {
                theme.colors.destructive
            } else {
                control.border
            })
            .bg(control.background)
            .text_color(theme.colors.foreground)
    }

    /// Styles `element` as the 16px check box with its mark, for checkboxes and
    /// grouped checkboxes. The element is the interactive root of the control.
    pub fn checkbox_box<T: Styled + ParentElement>(
        element: T,
        theme: &UiTheme,
        checked: bool,
        indeterminate: bool,
    ) -> T {
        let colors = theme.colors;
        let control = theme.control();
        let selected = checked || indeterminate;
        let element = element
            .flex()
            .flex_shrink_0()
            .items_center()
            .justify_center()
            .size(theme.space(4.))
            .rounded(box_radius(theme))
            .border_1()
            .border_color(if selected {
                colors.primary
            } else {
                control.border
            })
            .bg(if selected {
                colors.primary
            } else {
                control.background
            });
        if selected {
            element.child(
                lucide(if indeterminate {
                    LucideIcon::Minus
                } else {
                    LucideIcon::Check
                })
                .size(icon::sm(theme))
                .text_color(colors.primary_foreground),
            )
        } else {
            element
        }
    }

    /// Styles `element` as the 16px radio circle with its dot.
    pub fn radio_dot<T: Styled + ParentElement>(element: T, theme: &UiTheme, checked: bool) -> T {
        let colors = theme.colors;
        let control = theme.control();
        let element = element
            .flex()
            .flex_shrink_0()
            .items_center()
            .justify_center()
            .size(theme.space(4.))
            .rounded_full()
            .border_1()
            .border_color(if checked {
                colors.primary
            } else {
                control.border
            })
            .bg(if checked {
                colors.primary
            } else {
                control.background
            });
        if checked {
            element.child(
                div()
                    .size(theme.space(2.))
                    .rounded_full()
                    .bg(colors.primary_foreground),
            )
        } else {
            element
        }
    }

    /// The toggle look shared by Toggle and Toggle Group items: transparent at
    /// rest, muted when hovered or pressed, an input border when outlined.
    pub fn toggle<T: Styled>(
        element: T,
        theme: &UiTheme,
        pressed: bool,
        disabled: bool,
        outline: bool,
    ) -> T {
        let colors = theme.colors;
        let control = theme.control();
        let element = text::sm(element, theme)
            .border_1()
            .border_color(if outline {
                control.border
            } else {
                colors.background.opacity(0.)
            })
            .text_color(colors.foreground)
            .bg(if pressed {
                control.pressed
            } else {
                colors.background.opacity(0.)
            });
        disabled::interactive(element, disabled)
    }
}

/// The switch track and thumb colors for a checked or unchecked switch.
pub fn switch_colors(theme: &UiTheme, checked: bool) -> (Rgba, Rgba) {
    let control = theme.control();
    if checked {
        (theme.colors.primary, control.thumb_checked)
    } else {
        (control.track, control.thumb)
    }
}

/// An image inside a rounded frame. GPUI clips children to rectangles, so the
/// frame rounds itself and the image rounds to the frame's inner radius; the
/// image fills the frame's box and never sizes the frame from its aspect ratio.
pub fn clipped_image(
    source: impl Into<ImageSource>,
    radius: Pixels,
    fit: ObjectFit,
    theme: &UiTheme,
) -> Div {
    clipped_image_with(source, radius, fit, theme, |image| image)
}

/// [`clipped_image`] with access to the picture, for loading and fallback views.
pub fn clipped_image_with(
    source: impl Into<ImageSource>,
    radius: Pixels,
    fit: ObjectFit,
    theme: &UiTheme,
    configure: impl FnOnce(Img) -> Img,
) -> Div {
    div()
        .relative()
        .flex_shrink_0()
        .overflow_hidden()
        .rounded(radius)
        .bg(theme.colors.muted)
        .child(configure(
            img(source)
                .absolute()
                .inset_0()
                .size_full()
                .rounded(radius)
                .object_fit(fit),
        ))
}

/// A circular image, as in avatars.
pub fn round_image(source: impl Into<ImageSource>, size: Pixels, theme: &UiTheme) -> Div {
    clipped_image(source, size / 2., ObjectFit::Cover, theme).size(size)
}

/// Dismisses an overlay from a press outside it or the Escape key.
pub mod dismiss {
    use super::*;

    /// Runs `handler` when the pointer presses outside `element` or Escape is
    /// pressed while focus is inside it.
    pub fn on_outside<E: StatefulInteractiveElement>(
        element: E,
        handler: impl Fn(&mut Window, &mut gpui_kit::App) + 'static,
    ) -> E {
        let handler = std::rc::Rc::new(handler);
        let on_press = handler.clone();
        element
            .on_mouse_down_out(move |event, window, cx| {
                if event.button == MouseButton::Left {
                    on_press(window, cx)
                }
            })
            .on_key_down(move |event, window, cx| {
                if event.keystroke.key == "escape" {
                    handler(window, cx);
                    cx.stop_propagation();
                }
            })
    }
}

/// Hover-revealed content that never changes layout: the element keeps its
/// size and only its opacity follows `visible`.
pub fn hover_reveal<T: Styled>(element: T, visible: bool) -> T {
    element.opacity(if visible { 1. } else { 0. })
}

/// Content shown while the pointer is over the enclosing `.group(name)`
/// element, with no state and no re-render: opacity 0 at rest, 1 on hover.
/// Pass `pinned` to keep it visible, as for a selected row's actions.
pub fn hover_reveal_in_group<T: Styled + InteractiveElement>(
    element: T,
    group: impl Into<SharedString>,
    pinned: bool,
) -> T {
    if pinned {
        element
    } else {
        element
            .opacity(0.)
            .group_hover(group, |style| style.opacity(1.))
    }
}

/// Erases an element's type after styling, for callers that store children.
pub fn erase(element: impl IntoElement) -> AnyElement {
    element.into_any_element()
}

//! The app-owned shadcn Neutral theme for gpuicn.
//!
//! Source: shadcn/ui 4.19.0 at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`, Nova style.

use std::{sync::Arc, time::Duration};

use gpui_kit::{
    App, BoxShadow, ElementId, Global, Pixels, Rgba, SharedString, Styled, Subscription, Window,
    WindowAppearance, black, px,
};

#[path = "primitives.rs"]
pub mod primitives;

gpui_kit::actions!(
    gpuicn,
    [
        /// Move to the next keyboard tab stop.
        FocusNext,
        /// Move to the previous keyboard tab stop.
        FocusPrevious
    ]
);

struct Initialized;
impl Global for Initialized {}

/// Installs component actions, keyboard traversal and the default theme once.
/// Call this from application startup for both copied source and crate usage.
pub fn init(cx: &mut App) {
    if cx.has_global::<Initialized>() {
        return;
    }
    seed_component_fonts(cx);
    gpui_kit::init(cx);
    cx.set_global(Initialized);
    if !cx.has_global::<UiTheme>() {
        UiTheme::set(cx, UiTheme::neutral_light());
    } else {
        let theme = UiTheme::read(cx).clone();
        sync_component_theme(cx, theme);
    }
    cx.bind_keys([
        gpui_kit::KeyBinding::new("tab", FocusNext, None),
        gpui_kit::KeyBinding::new("shift-tab", FocusPrevious, None),
    ]);
    cx.on_action(|_: &FocusNext, cx| advance_focus(false, cx));
    cx.on_action(|_: &FocusPrevious, cx| advance_focus(true, cx));
    // Scoped component bindings take precedence over these window-wide defaults.
    #[cfg(target_family = "wasm")]
    {
        // Browser previews also accept macOS editing shortcuts.
        use gpui_kit::KeyBinding;
        use gpui_kit::base::input::{
            Copy, Cut, MoveEnd, MoveHome, MoveToNextWord, MoveToPreviousWord, Paste, Redo,
            SelectAll, SelectToNextWordEnd, SelectToPreviousWordStart, Undo,
        };
        cx.bind_keys([
            KeyBinding::new("cmd-a", SelectAll, Some("Input")),
            KeyBinding::new("cmd-c", Copy, Some("Input")),
            KeyBinding::new("cmd-v", Paste, Some("Input")),
            KeyBinding::new("cmd-x", Cut, Some("Input")),
            KeyBinding::new("cmd-left", MoveHome, Some("Input")),
            KeyBinding::new("cmd-right", MoveEnd, Some("Input")),
            KeyBinding::new("cmd-z", Undo, Some("Input")),
            KeyBinding::new("cmd-shift-z", Redo, Some("Input")),
            KeyBinding::new("alt-left", MoveToPreviousWord, Some("Input")),
            KeyBinding::new("alt-right", MoveToNextWord, Some("Input")),
            KeyBinding::new("alt-shift-left", SelectToPreviousWordStart, Some("Input")),
            KeyBinding::new("alt-shift-right", SelectToNextWordEnd, Some("Input")),
        ]);
    }
}

fn seed_component_fonts(cx: &mut App) {
    use gpui_kit::component::Theme;

    if cx.has_global::<Theme>() {
        return;
    }
    let fonts = if cx.has_global::<UiTheme>() {
        UiTheme::read(cx).fonts.clone()
    } else {
        UiTheme::neutral_light().fonts
    };
    let mut component = Theme::default();
    component.font_family = fonts.body;
    component.mono_font_family = fonts.mono;
    cx.set_global(component);
}

fn advance_focus(reverse: bool, cx: &mut App) {
    let Some(handle) = cx.active_window() else {
        return;
    };
    // Action dispatch still holds the window borrow until this callback returns.
    cx.defer(move |cx| {
        let _ = handle.update(cx, |_, window, cx| {
            if reverse {
                window.focus_prev(cx);
            } else {
                window.focus_next(cx);
            }
        });
    });
}

/// The active color mode.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ThemeMode {
    /// The Neutral light palette.
    Light,
    /// The Neutral dark palette.
    Dark,
}

/// Which of an application's two palettes is shown.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum Appearance {
    /// Always the light palette.
    Light,
    /// Always the dark palette.
    Dark,
    /// The palette matching the operating system's window appearance.
    #[default]
    System,
}

impl Appearance {
    /// The mode this appearance shows under the given system appearance.
    pub fn resolve(self, system: WindowAppearance) -> ThemeMode {
        match self {
            Appearance::Light => ThemeMode::Light,
            Appearance::Dark => ThemeMode::Dark,
            Appearance::System => match system {
                WindowAppearance::Dark | WindowAppearance::VibrantDark => ThemeMode::Dark,
                WindowAppearance::Light | WindowAppearance::VibrantLight => ThemeMode::Light,
            },
        }
    }
}

/// The application's light and dark themes and which one it shows.
#[derive(Clone)]
struct ThemePair {
    light: UiTheme,
    dark: UiTheme,
    appearance: Appearance,
}
impl Global for ThemePair {}

/// Swaps palettes when the operating system's appearance changes while the
/// application follows it. Call it for each window the application opens and
/// keep the subscription; `app::run` does this for the first window.
pub fn follow_system(window: &mut Window, cx: &mut App) -> Subscription {
    UiTheme::apply_appearance(cx);
    window.observe_window_appearance(|_, cx| UiTheme::apply_appearance(cx))
}

/// Semantic colors consumed by installed components.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiColors {
    /// App background.
    pub background: Rgba,
    /// Default foreground.
    pub foreground: Rgba,
    /// Card background.
    pub card: Rgba,
    /// Card foreground.
    pub card_foreground: Rgba,
    /// Popover background.
    pub popover: Rgba,
    /// Popover foreground.
    pub popover_foreground: Rgba,
    /// Primary control background.
    pub primary: Rgba,
    /// Primary control foreground.
    pub primary_foreground: Rgba,
    /// Secondary control background.
    pub secondary: Rgba,
    /// Secondary control foreground.
    pub secondary_foreground: Rgba,
    /// Muted background.
    pub muted: Rgba,
    /// Muted foreground.
    pub muted_foreground: Rgba,
    /// Accent background.
    pub accent: Rgba,
    /// Accent foreground.
    pub accent_foreground: Rgba,
    /// Destructive action color.
    pub destructive: Rgba,
    /// Text on a solid `destructive` surface.
    pub destructive_foreground: Rgba,
    /// Positive status, such as a completed upload or an online presence dot.
    pub success: Rgba,
    /// Text on a `success` fill.
    pub success_foreground: Rgba,
    /// Cautionary status, such as a permalink highlight or a pending state.
    pub warning: Rgba,
    /// Text on a `warning` fill.
    pub warning_foreground: Rgba,
    /// Informational status.
    pub info: Rgba,
    /// Text on an `info` fill.
    pub info_foreground: Rgba,
    /// Default border.
    pub border: Rgba,
    /// Input border.
    pub input: Rgba,
    /// Focus ring.
    pub ring: Rgba,
    /// First chart color.
    pub chart_1: Rgba,
    /// Second chart color.
    pub chart_2: Rgba,
    /// Third chart color.
    pub chart_3: Rgba,
    /// Fourth chart color.
    pub chart_4: Rgba,
    /// Fifth chart color.
    pub chart_5: Rgba,
    /// Sidebar background.
    pub sidebar: Rgba,
    /// Sidebar foreground.
    pub sidebar_foreground: Rgba,
    /// Sidebar primary background.
    pub sidebar_primary: Rgba,
    /// Sidebar primary foreground.
    pub sidebar_primary_foreground: Rgba,
    /// Sidebar accent background.
    pub sidebar_accent: Rgba,
    /// Sidebar accent foreground.
    pub sidebar_accent_foreground: Rgba,
    /// Sidebar border.
    pub sidebar_border: Rgba,
    /// Sidebar focus border color.
    pub sidebar_ring: Rgba,
    /// Scrim behind modal surfaces.
    pub overlay: Rgba,
}

/// Theme font family names. Applications own font loading.
#[derive(Clone, Debug, PartialEq)]
pub struct UiFonts {
    /// Default body family.
    pub body: SharedString,
    /// Default heading family.
    pub heading: SharedString,
    /// Default monospace family.
    pub mono: SharedString,
}

/// Corner radii derived from shadcn's 10px base radius.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiRadius {
    /// Backward-compatible alias for [`Self::lg`].
    pub base: Pixels,
    /// Six pixels (`radius * 0.6`).
    pub sm: Pixels,
    /// Eight pixels (`radius * 0.8`).
    pub md: Pixels,
    /// Ten pixels (the configured base radius).
    pub lg: Pixels,
    /// Fourteen pixels (`radius * 1.4`).
    pub xl: Pixels,
    /// Eighteen pixels (`radius * 1.8`).
    pub two_xl: Pixels,
    /// Twenty-two pixels (`radius * 2.2`).
    pub three_xl: Pixels,
    /// Twenty-six pixels (`radius * 2.6`).
    pub four_xl: Pixels,
}

impl UiRadius {
    /// Derives the complete Nova radius scale from one nonnegative base radius.
    pub fn new(base: Pixels) -> Self {
        assert!(f32::from(base).is_finite() && base >= px(0.));
        Self {
            base,
            sm: base * 0.6,
            md: base * 0.8,
            lg: base,
            xl: base * 1.4,
            two_xl: base * 1.8,
            three_xl: base * 2.2,
            four_xl: base * 2.6,
        }
    }
}

/// Shared UI transition durations. Honor these alongside `App::reduce_motion()`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct UiMotion {
    /// Thumb and small-state transitions (150ms by default).
    pub fast: Duration,
    /// Panel/layout transitions (200ms by default).
    pub normal: Duration,
    /// Application preference; true removes movement without removing state feedback.
    pub reduced: bool,
    /// Shared easing for reversible state transitions.
    pub easing: UiEasing,
}
impl Default for UiMotion {
    fn default() -> Self {
        Self {
            fast: Duration::from_millis(150),
            normal: Duration::from_millis(200),
            reduced: false,
            easing: UiEasing::EaseInOut,
        }
    }
}

/// Curves supported by the shared native transition helper.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum UiEasing {
    /// Constant-speed motion, as used by shadcn sidebar layout transitions.
    Linear,
    /// Fast response followed by a smooth stop.
    EaseOut,
    /// Smooth acceleration and deceleration for changes within a layout.
    #[default]
    EaseInOut,
    /// Quick start and a long settle (`cubic-bezier(0.22, 1, 0.36, 1)`), for
    /// surfaces that slide in from an edge, such as drawers and sheets.
    Emphasized,
}
impl UiEasing {
    fn sample(self, progress: f32) -> f32 {
        match self {
            Self::Linear => progress,
            Self::EaseOut => gpui_kit::ease_out_quint()(progress),
            Self::EaseInOut => gpui_kit::ease_in_out(progress),
            Self::Emphasized => gpui_kit::base::motion::Easing::CubicBezier {
                x1: 0.22,
                y1: 1.,
                x2: 0.36,
                y2: 1.,
            }
            .sample(progress),
        }
    }
}

/// Returns a smoothly retargetable value for one stable, caller-named property.
/// Starts at the target on mount; rapid reversals continue from the current value.
/// Honors theme and GPUI reduced-motion settings and schedules no idle frames.
/// Use for state changes, never for pointer-drag coordinates or keyboard navigation.
/// Native layout transitions perform layout work; retain expensive child entities.
pub fn transition_value(
    id: impl Into<ElementId>,
    target: f32,
    duration: Duration,
    window: &mut Window,
    cx: &mut App,
) -> f32 {
    let easing = UiTheme::read(cx).motion.easing;
    transition_with(id, target, duration, easing, window, cx)
}

/// [`transition_value`] with an explicit curve, for the few surfaces whose motion
/// differs from the theme default (drawers slide with [`UiEasing::Emphasized`]).
pub fn transition_with(
    id: impl Into<ElementId>,
    target: f32,
    duration: Duration,
    easing: UiEasing,
    window: &mut Window,
    cx: &mut App,
) -> f32 {
    assert!(target.is_finite(), "transition targets must be finite");
    gpui_kit::base::motion::transition(
        id.into(),
        target,
        motion_policy(duration, easing, cx),
        window,
        cx,
    )
}

/// Shares the theme's disclosure and notification timing with Kit's presence lifecycle.
/// Returns a sample whose `progress` runs 0→1 while entering and 1→0 while leaving, so
/// a surface fades or scales with it; `should_render()` keeps the element mounted
/// until the exit transition has finished.
#[doc(hidden)]
pub fn presence(
    id: impl Into<ElementId>,
    present: bool,
    window: &mut Window,
    cx: &mut App,
) -> gpui_kit::base::motion::PresenceSample {
    let motion = UiTheme::read(cx).motion;
    presence_with(id, present, motion.fast, motion.easing, window, cx)
}

/// [`presence`] with explicit timing and curve, for panels that take the theme's
/// `normal` duration or a different easing.
#[doc(hidden)]
pub fn presence_with(
    id: impl Into<ElementId>,
    present: bool,
    duration: Duration,
    easing: UiEasing,
    window: &mut Window,
    cx: &mut App,
) -> gpui_kit::base::motion::PresenceSample {
    gpui_kit::base::motion::Presence::new(id.into(), present)
        .transition(motion_policy(duration, easing, cx))
        .sample(window, cx)
}

/// The one place motion honors the theme and platform reduced-motion settings.
fn motion_policy(
    duration: Duration,
    easing: UiEasing,
    cx: &App,
) -> gpui_kit::base::motion::Transition {
    let duration = if UiTheme::read(cx).motion.reduced || cx.reduce_motion() {
        Duration::ZERO
    } else {
        duration
    };
    gpui_kit::base::motion::Transition::new(duration).ease(move |progress| easing.sample(progress))
}

